output_text:
[
  {
    "id": "no_cart_in_single_file_shelf_aisle",
    "text": "Carts are prohibited in single-file aisles flanked by shelf faces, a clearance-and-shelf relation that generalizes across layouts rather than depending on particular coordinates.",
    "abstraction": {
      "state_properties": {
        "singleFileHorizontalClearance": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "opposingShelfFaces": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "shopperOnlyShelfAisle": {
          "and": [
            "singleFileHorizontalClearance",
            "opposingShelfFaces"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "shopperOnlyShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_cart_entry_to_shelf_canyon",
    "text": "An agent must not push a cart from an open area into a single-file aisle between opposing shelves, which captures the cart drop before entering either observed narrow aisle without naming its position.",
    "abstraction": {
      "state_properties": {
        "singleFileHorizontalClearance": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "opposingShelfFaces": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "shopperOnlyShelfAisle": {
          "and": [
            "singleFileHorizontalClearance",
            "opposingShelfFaces"
          ]
        }
      },
      "events": {
        "enterShopperOnlyShelfAisle": {
          "pre": {
            "not": "shopperOnlyShelfAisle"
          },
          "post": "shopperOnlyShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "enterShopperOnlyShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_cart_motion_in_single_file_clearance",
    "text": "Carts should not be moved while in any single-file horizontal passage, a geometry-based pedestrian-clearance norm that can apply even if the surrounding objects are rearranged.",
    "abstraction": {
      "state_properties": {
        "singleFileHorizontalClearance": {
          "le": [
            "freeWidthH",
            1
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileHorizontalClearance",
          "MOVE"
        ]
      }
    }
  },
  {
    "id": "cartless_interaction_in_shelf_canyon",
    "text": "Shelf interactions performed inside a single-file aisle between opposing shelf faces must be done without a cart, distinguishing narrow in-aisle item access from wide-aisle item access.",
    "abstraction": {
      "state_properties": {
        "singleFileHorizontalClearance": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "opposingShelfFaces": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "shopperOnlyShelfAisle": {
          "and": [
            "singleFileHorizontalClearance",
            "opposingShelfFaces"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "shopperOnlyShelfAisle",
          "INTERACT"
        ]
      }
    }
  },
  {
    "id": "retrieve_temporarily_parked_cart",
    "text": "After parking a cart in a cart-accessible aisle, the agent is obliged to recover a cart before the trajectory ends, which explains returning to the parked cart independently of where the aisle is located.",
    "abstraction": {
      "state_properties": {
        "wideHorizontalAisle": {
          "ge": [
            "freeWidthH",
            3
          ]
        },
        "cartAccessibleAisle": {
          "and": [
            "wideHorizontalAisle",
            {
              "not": {
                "and": [
                  "shelfE",
                  "shelfW"
                ]
              }
            }
          ]
        }
      },
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "hasCart",
              "cartAccessibleAisle",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "recoverCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCart",
      "discharge": "recoverCart"
    }
  },
  {
    "id": "park_cart_only_in_open_wide_aisle",
    "text": "If a cart is put down, it should be put down only in an open wide aisle rather than next to shelves or in a constrained passage, a relational blocking-avoidance rule not tied to a particular parking coordinate.",
    "abstraction": {
      "state_properties": {
        "openWideAisle": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                3
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "putDownCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "putDownCart",
          {
            "not": "openWideAisle"
          }
        ]
      }
    }
  },
  {
    "id": "must_acquire_cart_for_trip",
    "text": "At the start of a shopping trip the agent is obliged to acquire a cart, expressed by the functional transition to hasCart rather than by the observed cart-station coordinate.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "acquireCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "acquireCart"
    }
  },
  {
    "id": "exit_with_acquired_cart",
    "text": "Once an agent has acquired a cart, the agent must leave with a cart, a role-based rule that remains meaningful if entrances, exits, and cart stations move.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "acquireCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "acquireCart",
      "discharge": {
        "and": [
          "EXIT",
          "hasCart"
        ]
      }
    }
  }
]
